parameters.jsonBody:
={
  "name": "Follow-up: {{ $json.first_name }} {{ $json.last_name }} ({{ $json.company_name || 'N/A' }})",
  "description": "## Lead Info\n- **Nome:** {{ $json.first_name }} {{ $json.last_name }}\n- **Email:** {{ $json.email }}\n- **Empresa:** {{ $json.company_name || 'N/A' }}\n- **Cargo:** {{ $json.role || 'N/A' }}\n- **Score:** {{ $json.lead_score }}\n- **Emails enviados:** {{ $json.emails_sent }}\n- **Emails abertos:** {{ $json.emails_opened }}\n- **Replies:** {{ $json.emails_replied }}\n\n## Acao\nResponder ao lead e agendar meeting.\n\n---\n*Criado automaticamente pelo CRM*",
  "status": "to do",
  "priority": {{ $json.lead_score >= 70 ? 1 : $json.lead_score >= 50 ? 2 : 3 }},
  "due_date": {{ Date.now() + 24 * 60 * 60 * 1000 }},
  "tags": ["outbound", "follow-up", "auto-created"],
  "custom_fields": [
    {
      "id": "CONFIGURE_CF_LEAD_SCORE_ID",
      "value": {{ $json.lead_score }}
    },
    {
      "id": "CONFIGURE_CF_LEAD_EMAIL_ID",
      "value": "{{ $json.email }}"
    }
  ]
}

={
  "name": "Meeting: {{ $json.first_name }} {{ $json.last_name }} ({{ $json.company_name || 'N/A' }})",
  "description": "## Lead Info
- **Nome:** {{ $json.first_name }} {{ $json.last_name }}
- **Email:** {{ $json.email }}
- **Empresa:** {{ $json.company_name || 'N/A' }}
